import sympy
import math

def build_instance(rng):
    constant_term = rng.randint(-10, 10)
    left_endpoint = rng.randint(-10, 10)
    right_endpoint = rng.randint(left_endpoint + 1, 10)
    x = sympy.symbols('x', real=True)
    P = x ** 3 - 3 * x ** 2 + 2 * x + constant_term
    roots = sympy.solvers.solve(P, x)
    real_roots = [root.evalf() for root in roots if root.is_real]
    count = sum((1 for root in real_roots if left_endpoint <= root <= right_endpoint))
    answer = count
    check = sum((1 for root in sympy.solvers.solve(P, x) if root.is_real and left_endpoint <= root <= right_endpoint))
    assert answer == check, f'answer={answer} check={check}'
    parameters = {'constant_term': constant_term, 'left_endpoint': left_endpoint, 'right_endpoint': right_endpoint}
    return (parameters, answer, check)



