import sympy

def build_instance(rng):
    first_term = rng.randint(-10, 10)
    common_difference = rng.randint(-5, 5)
    term_count = rng.randint(1, 10)
    terms = [first_term + i * common_difference for i in range(term_count)]
    product = 1
    for term in terms:
        product *= term
    answer = product
    check = sympy.prod([first_term + i * common_difference for i in range(term_count)])
    parameters = {'first_term': first_term, 'common_difference': common_difference, 'term_count': term_count}
    return (parameters, answer, check)



